-- Conteúdo do PDF antigo adaptado, sem sobrescrever edições da banda.
CREATE TABLE media_assets (
 id TEXT PRIMARY KEY,
 record_id TEXT NOT NULL UNIQUE REFERENCES records(id) ON DELETE CASCADE,
 content TEXT NOT NULL,
 mime TEXT NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
UPDATE records SET data='{"title": "Sislop · biografia", "category": "Biografia", "body": "Formada em 2012, a Sislop desenvolve um trabalho autoral que passa pelo indie rock, pelo rock alternativo e pelo dream pop, com referências ao marabaixo. Suas músicas partem de experiências reais e dos encontros e desencontros da vida cotidiana.\n\nHoje, Antônio Anísio, Breno Phernan, Cassio Ledo e Henrique Melo constroem juntos o próximo capítulo da banda: o álbum DIAMANTADO, em processo de gravação e ainda sem data de lançamento definida.", "notes": "Fonte: mídia kit fornecido pela banda (PDF de janeiro de 2022), atualizado com as informações desta conversa. Revisar antes de publicar. Texto de apresentação reescrito a partir do PDF e da formação atual. Não inclui estatísticas antigas, telefone sem confirmação ou anúncio do EP citado no material de 2022.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}',updated_by='adaptacao-midia-kit',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='839fdfcf-557c-5aa1-8091-f87d9d21ed5b' AND updated_by='planejamento-inicial';
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('555e0e80-b256-5429-a9f7-c5306bd4bbec','media','{"title": "Uma história que começou em 2012", "category": "História", "body": "A Sislop nasceu em 2012, a partir dos encontros de Antônio Anísio e Breno Phernan, amigos desde o ensino médio. Ao lado de Flávio Fj e Ben Alves, eles construíram a primeira formação da banda.\n\nEm 2013, a Sislop lançou “Labirinto”, seu primeiro single. A trajetória seguiu com trabalhos como “Malditas Lembranças” e “Quinta-feira”, ampliando seu repertório autoral e suas referências.", "notes": "Fonte: mídia kit fornecido pela banda (PDF de janeiro de 2022), atualizado com as informações desta conversa. Revisar antes de publicar. ", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('b8a61f88-cd3f-541e-bc52-5cd5cfb4e896','media','{"title": "Entre o indie rock e novas atmosferas", "category": "Sonoridade", "body": "Indie rock, rock alternativo e dream pop se encontram na sonoridade da Sislop, com referências ao marabaixo, ritmo afro-brasileiro tradicional do Amapá.\n\nAs composições atravessam experiências do cotidiano, obstáculos, desilusões e a busca por sentido. Histórias pessoais se transformam em música, criando espaço para identificação e conexão com o público.", "notes": "Fonte: mídia kit fornecido pela banda (PDF de janeiro de 2022), atualizado com as informações desta conversa. Revisar antes de publicar. Confirmar se essa descrição ainda representa a sonoridade atual de DIAMANTADO.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('05a7eb14-6ac2-517e-8415-833b28e4947c','media','{"title": "Quatro integrantes. Uma construção coletiva.", "category": "Integrantes", "body": "Antônio Anísio · voz e guitarra\nCofundador da Sislop ao lado de Breno Phernan, começou a compor pouco depois de ganhar seu primeiro violão.\n\nBreno Phernan · teclado e voz\nCofundador da banda, reúne estudos de piano e experiências em festivais e projetos culturais.\n\nCassio Ledo · bateria\nSeu contato com a bateria começou ainda cedo, e a conexão com a Sislop nasceu dos encontros nos palcos.\n\nHenrique Melo · baixo e voz\nSua trajetória passa por diferentes instrumentos e pela produção musical. A conexão com a banda se transformou em uma parceria de palco e de vida.", "notes": "Fonte: mídia kit fornecido pela banda (PDF de janeiro de 2022), atualizado com as informações desta conversa. Revisar antes de publicar. Formação atual de quatro integrantes confirmada pela banda; Jacó não foi incluído na formação atual. Funções cruzadas com o mapa de palco enviado. As biografias foram resumidas sem inventar qualificações.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('3027fbdb-62a2-5687-b39f-ded30034c435','media','{"title": "Primeiros trabalhos autorais", "category": "Discografia", "body": "2013 · Labirinto\nPrimeiro single da Sislop.\n\nMalditas Lembranças\nSingle autoral da trajetória da banda.\n\nQuinta-feira\nSingle autoral da trajetória da banda.", "notes": "Fonte: mídia kit fornecido pela banda (PDF de janeiro de 2022), atualizado com as informações desta conversa. Revisar antes de publicar. Adicionar links oficiais e datas dos outros singles quando confirmados. Não foram inferidos links de streaming.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('12695209-c62f-551e-89f1-d3bbbf9b57ff','media','{"title": "DIAMANTADO · o próximo capítulo", "category": "Release", "body": "A Sislop está em processo de gravação do álbum DIAMANTADO. O projeto marca o próximo capítulo da banda, construído entre sessões de estúdio, novas ideias e o trabalho coletivo de seus quatro integrantes.\n\nA data de lançamento será anunciada após a definição do cronograma.", "notes": "Baseado nas informações atuais da banda. Lançamento ainda a definir. Complementar com conceito do disco, tracklist, créditos e fotos após aprovação; não usar o antigo anúncio de EP do PDF.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('0f2cdc30-912e-5663-9995-5334fe86c2f6','media','{"title": "Mapa de palco · formação de quatro integrantes", "category": "Mapa de palco", "body": "Referência de posicionamento, vista superior com a frente do palco embaixo.\n\nCentro / frente · Antônio Anísio: guitarra e vocal; retorno 1.\nDireita / frente · Henrique Melo: baixo e vocal; retorno 2.\nEsquerda / frente · Breno Phernan: teclado e vocal; retorno 3.\nCentro / fundo · Cassio Ledo: bateria; retorno 4.\n\nAmplificador de guitarra ao fundo, à esquerda. Amplificador de baixo ao fundo, à direita. Três posições de voz com pedestal, uma em cada posição frontal.", "notes": "Adaptado da imagem de referência enviada pela banda. A imagem original repete o número 4 para retornos e não mostra claramente o retorno 3; aqui a numeração foi organizada em 1/2/3/4 por posição. Confirmar essa organização com a banda e a produção. A figura é um esquema de referência, sem escala, não um inventário de equipamentos disponíveis.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('c0129394-2ef1-5e46-a6e2-7038d9b445f5','media','{"title": "Necessidades técnicas · base para alinhamento", "category": "Ficha técnica", "body": "Formação: guitarra/vocal, baixo/vocal, teclado/vocal e bateria.\n\nReferência de estrutura:\n• 4 retornos, com distribuição a confirmar com o técnico.\n• 3 microfones de voz com pedestais.\n• 1 amplificador de guitarra.\n• 1 amplificador de baixo.\n• Espaço para bateria ao fundo, preferencialmente com tapete.\n\nA microfonação da bateria, conexões e DIs do teclado, canais de entrada, alimentação elétrica e fornecimento de backline devem ser combinados com a produção.\n\nO mapa de referência sugere palco de 8 m de largura por 6 m de profundidade. Confirmar a viabilidade e possíveis adaptações para cada espaço.", "notes": "Baseado no mapa de palco fornecido. Os 3 microfones indicados são de voz; não representam a microfonação total da apresentação. Marcas de equipamentos da ilustração não foram transformadas em exigências. Preparar input list detalhada após confirmar saídas, microfones e backline com a banda.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('d63c96df-99a8-5736-a82d-16829670c4ee','media','{"title": "Fotografia secundária · material a selecionar", "category": "Fotos", "body": "Fotografias complementares da banda para apresentação e divulgação.", "notes": "A foto enviada nesta conversa não é a imagem principal, conforme Henrique. Usar apenas como foto secundária. O arquivo não ficou disponível para cópia no workspace; enviar pelo campo de imagem deste registro no portal. Créditos e autorização de uso devem acompanhar a foto. Nenhuma imagem de capa foi escolhida automaticamente.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
INSERT OR IGNORE INTO records(id,kind,data,updated_by) VALUES('58f1c496-d702-5dd3-bc26-c0c3a1f58200','media','{"title": "Links, contatos e métricas · atualização pendente", "category": "Outros", "body": "Os links oficiais e os materiais de imprensa estão em atualização. Para informações, fale com sisloprock@gmail.com.", "notes": "Fonte: mídia kit fornecido pela banda (PDF de janeiro de 2022), atualizado com as informações desta conversa. Revisar antes de publicar. Informações antigas mantidas apenas nesta observação interna, sem publicação: telefone +55 11 98344-8496; Instagram @sislopoficial; referência Facebook /sislop; Instagram 1.005 seguidores; YouTube 790 inscritos e 31.776 visualizações; Facebook 2.918 seguidores. Confirmar telefone, URLs e dados atuais antes de usar. Não apresentar esses números como atuais.", "status": "Em revisão", "published": false, "origin": "Adaptado do material da banda"}','adaptacao-midia-kit');
